scenario.en:
// Claim: isAdult works for every user.
function isAdult(user) {
  return new Date().getFullYear() - user.birthYear >= 18;
}

// Test suite — all green:
isAdult({ birthYear: 1990 }); // true  — correct
isAdult({ birthYear: 2020 }); // false — correct
isAdult({ birthYear: 1900 }); // true  — correct

